blocks.text:
/* unvisited link */
a:link {
  color: #FF0000;
}

/* visited
link */
a:visited {
  color: #00FF00;
}

/* mouse over link */

a:hover {
  color: #FF00FF;
}

/* selected link */
a:active {

  color: #0000FF;
}

p {
  display: none;

background-color: yellow;
  padding: 20px;
}

div:hover p {
  display: block;
}
